import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Calculate t-statistics for all features
    t_stats = []
    for i, fid in enumerate(feats.ids):
        t_stat, _ = stats.ttest_ind(feats.x[:,i][feats.y==1], feats.x[:,i][feats.y==0])
        t_stats.append(abs(t_stat))

    # Sort by t-statistic magnitude
    sorted_indices = np.argsort(t_stats)[::-1]

    # Select top features, avoiding near-duplicates
    drivers = []
    selected = set()
    near_dup_pairs = {
        ('PNU10', 'TSP11'), ('MSEQ10', 'LIZP11P'), ('MSEQ10', 'WCQF6'), 
        ('WCQF6', 'LIZP11P'), ('JMD15', 'CZEW19'), ('OMB12A', 'WUL6'),
        ('OMB12A', 'UZFR6'), ('CTM15', 'NESJ4'), ('PFS16', 'ERV8'),
        ('WUL6', 'UZFR6'), ('MSEQ10', 'CZEW19'), ('CZER19B', 'EATE2A'),
        ('VRKS3', 'HWX7L'), ('CZER19B', 'IIH16'), ('ZSTN15L', 'LIZP11P'),
        ('CTM15', 'JMD15'), ('WCQF6', 'CZEW19'), ('MSEQ10', 'ZSTN15L'),
        ('JPO19', 'EATE2A'), ('ZSTN15L', 'WCQF6')
    }

    for idx in sorted_indices:
        fid = feats.ids[idx]
        if fid in selected:
            continue

        # Check if this feature's near-duplicate is already selected
        skip = False
        for dup_pair in near_dup_pairs:
            if dup_pair[0] == fid and dup_pair[1] in selected:
                skip = True
                break
            elif dup_pair[1] == fid and dup_pair[0] in selected:
                skip = True
                break

        if not skip:
            drivers.append(fid)
            selected.add(fid)
            # Add near-duplicate to selected set
            for dup_pair in near_dup_pairs:
                if dup_pair[0] == fid:
                    selected.add(dup_pair[1])
                elif dup_pair[1] == fid:
                    selected.add(dup_pair[0])

        if len(drivers) >= MAX_DRIVERS:
            break

    # Limit to at most 4 drivers as per checker report
    if len(drivers) > 4:
        drivers = drivers[:4]

    # Build columns and products lists
    columns = list(feats.ids)
    products = []

    # Simple weighted score using top features
    loadings = {}
    for i, fid in enumerate(feats.ids):
        if fid in drivers:
            loadings[fid] = t_stats[i] / max(t_stats) if max(t_stats) > 0 else 0

    # Keep model simple - use minimal interaction terms
    if len(drivers) >= 2:
        products = [(drivers[0], drivers[1])]

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )
